input.new_string:
import { schema, string } from 'tidyvalid'

const signup = schema({
  email: string().email('email must be an email address'),
  password: string().min(8, 'password must be at least 8 characters'),
})

/**
 * Checks a sign-up form before an account is made. Returns { ok, errors }, one message for each problem.
 */
export function validateSignup(form) {
  const result = signup.check(form)
  return result.ok ? { ok: true, errors: [] } : { ok: false, errors: result.issues.map((issue) => issue.message) }
}
